-- The spells of the Nightbane RPG core book the catalog did not already hold in
-- a form a Nightbane character can reach. Printed 126-150; step 1 of the
-- extraction plan in apps/character-creator/docs/surveys/nightbane-core.md.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-spells.sql
--
-- Read from the book's TEXT LAYER (.cache/books/nightbane-core, page_offset 1)
-- by three extraction slices, every row then checked against the page by a
-- separate reconcile pass. Printed 140 is a welded page and was read off a render.
--
-- THE BOOK DESCRIBES 131 SPELLS AND THIS FILE WRITES 39. The other 92 are
-- already here, identical in level and in the P.P.E. the stat block prints, on
-- rows tagged NULL or `both` - which a Nightbane character already sees. They
-- get no row, the way Heroes Unlimited's 54 shared spells got none
-- (add-hu-core-spells.sql). A Nightbane caster's class will name its spells in a
-- list; the list names those rows directly.
--
-- THE SURVEY'S CENTRAL SPELL FINDING WAS WRONG, AND THIS IS WHERE IT DIED. It
-- read the book's index (printed 126-127) and concluded Nightbane prints its own,
-- cheaper costs for 26 shared spells. THE INDEX MISPRINTS. Sixteen of those 26
-- print, in their own stat blocks, exactly the cost the catalog already holds -
-- See Aura 6 where the index says 2, eleven more of levels one to three at the
-- Rifts figure, Metamorphosis: Mist 250 where the index says 200. The stat block
-- is the second reading and agrees with an independent third (the catalog's
-- source books); the index is the outlier. book-survey 4c: settle a book
-- disagreeing with itself by counting readings, not by the rule.
--
-- WHAT IS WRITTEN:
--
-- * 27 NEW INVOCATIONS, plain names, `system = 'nightbane'`, tradition NULL -
--   the book's own general spells with no catalog row at all (the Nightlands
--   rituals, Sense Nightbane, Bind Nightbane, Magic Armor, Night Vision...).
--   Names follow the INDEX where it and the heading differ, the rule
--   add-hu-core-spells.sql also followed: Night Vision (heading: Nightvision),
--   Negation (Negation (of Magic)), Nightlands Portal (Nightland Portal),
--   Temporary Insanity (Curse: Temporary Insanity); "(Ritual)" suffixes are the
--   heading's and are dropped.
--
-- * 12 RETELLINGS as `Nightbane: <name>`, `tradition = 'nightbane'`, beside the
--   established row - the shape the tradition namespaces already use. Two kinds:
--     - TEN where both of the book's readings agree on a cost the catalog does
--       not hold: six level-four spells at 7 against 10 (Astral Projection,
--       Charismatic Aura, Cure Minor Disorders, Energy Field, Shadow Meld,
--       Trance), Luck Curse and Metamorphosis: Human at 35 against 40, Minor
--       Curse 30 against 35, Protection Circle: Superior 250 against 300.
--     - TWO identical in level and cost whose only catalog row is tagged
--       `rifts`, which a Nightbane character cannot see: Wards, Summon and
--       Control Rain.
--   A retelling takes the ESTABLISHED row's name, not the index's: the index
--   calls the second of those `Summon Rain`; the heading and the catalog row
--   both say `Summon and Control Rain`.
--
-- THE `same_spell_as` LINKS WERE DECIDED BY scripts/same-spell-lib.mjs, NOT BY
-- NAME, following zzzzzzzzzz-mr-living-fire-spells.sql; regression.mjs runs the
-- same detector over every link on a clean rebuild. It approved 9 of 12. The
-- three it refused ARE the same spell, and the refusal is the catalog row's
-- shape rather than a mechanical difference - recorded here so nobody links
-- them by hand:
--
--   * Luck Curse   - the page's save is "Standard"; the catalog row annotates
--                    "Standard; 12 by spell, 16 by ritual", so the numbers differ
--   * Minor Curse  - the catalog's description is a 417-character paraphrase of
--                    this 2,479-character entry; the length floor refuses it
--   * Wards        - both of the above
--
-- ONE PHRASE WAS READ OFF A RENDER: Charm Weapon's "(like vampires or entities)",
-- which the text layer on printed 134 garbles.
--
-- THE BOOK DISAGREES WITH ITSELF ON THREE OF THESE ROWS. The stat block is
-- stored and the index's figure goes in variant_note: Impression (index 4,
-- block 5), Charm Weapon (15, 12), Temporary Enchantment (30, 70).
--
-- NOT WRITTEN, and why:
--   * Summon Entity - named in the index at 250 P.P.E. and described nowhere in
--     the chapter. An index entry with no stat block has nothing to store.
--   * Five level 14-15 spells (Close Rift, Id Barrier, Restoration, Dimensional
--     Portal, Teleport: Superior) are described but absent from the index; all
--     five are already here, identical.

INSERT INTO spells
  (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition)
VALUES
  ('Sense Nightbane', 1, 3, NULL, NULL, 'import', 'Nightbane RPG p.128', 'nightbane', '200 ft (61.0 m) area.', '1 minute (4 melees) per level of experience.', NULL, 'None', NULL, NULL, 'This invocation works like the natural Nightbane ability to sense others of their kind, enabling the sorcerer to sense the presence of Nightbane within the area. The ability does not tell the exact location or numbers of Nightbane, but will reveal whether there is more than one, and roughly how far away they are (within 30 ft/9.1 m).', NULL, NULL),
  ('Sense P.P.E.', 1, 3, NULL, NULL, 'import', 'Nightbane RPG p.128', 'nightbane', '120 ft (36.5 m) area.', '1 minute (4 melees) per level of experience.', NULL, 'Standard; ley lines and inanimate objects have no saving throw.', NULL, NULL, 'This invocation allows the sorcerer to sense the presence of potential psychic energy (P.P.E.). Like a Geiger counter, the individual can tell if he is near (within 20 ft/6.1 m) or far (at the limit of the magic''s range). This magic ability should not be confused with "sense magic." It cannot pick up magic emanations, so it will not identify most magic objects, enchantments or spell casting. What this magic does provide is an indication of potential psychic energy within the area - people, places, supernatural beings, animals and other sources of P.P.E. This can be important if there is a need to draw additional P.P.E. from another source(s). First, the magic will alert the sorcerer to the presence of potential psychic energy in its range area. Second, the arcanist can determine the approximate amount of P.P.E. each individual currently possesses. Little is 1-5 P.P.E., typical is 6-15, medium is 16-30, a lot is 31-60, vast (and often unnatural) is 61 and higher, incredible is 500 P.P.E. and higher. Objects only register potential psychic energy if they are possessed/inhabited by a living force.', NULL, NULL),
  ('Ritual: Call Creature of Light', 2, 10, NULL, NULL, 'import', 'Nightbane RPG p.130', 'nightbane', '10 miles (16 km) per level of the caster', 'Instant', NULL, 'None', NULL, 'Fifteen minutes', 'This ritual invocation contacts the nearest creature of light in the area. The Guardians are just one such group; more of these mysterious beings will be described in future Nightbane sourcebooks. The creature of light will sense that his/her presence is required by the spell caster and the ritual will also impart an empathic flash of the summoner''s personality and intentions. This means that an evil sorcerer trying to ambush the creature of light will be automatically unmasked by the invocation. Whether or not any creatures of light are nearby, or willing to help, is up to the Game Master.', NULL, NULL),
  ('Impression', 3, 5, NULL, 'The book''s own index (printed 126-127) lists this at 4 P.P.E.; the stat block prints 5, which is stored.', 'import', 'Nightbane RPG p.131', 'nightbane', 'Touch', 'One melee (15 seconds).', NULL, 'None.', NULL, NULL, 'The sorcerer is magically instilled with the ability to receive psychic impressions from an object about its previous owner. The following information will be revealed. 1. General alignment; good, selfish, or evil. 2. Human or not human (specific nature of the inhumanness is not revealed). 3. Old or young. 4. Male or female. 5. Healthy, sick or hurt. 6. Whether the object is important or valuable to the individual, although the reason is not revealed.', NULL, NULL),
  ('Magic Armor', 3, 10, NULL, NULL, 'import', 'Nightbane RPG p.131', 'nightbane', 'Self or other.', '4 melees (1 minute) per level of the spell caster', NULL, 'None.', NULL, NULL, 'This powerful spell instantly creates an invisible, weightless, noiseless, full suit of mystic armor upon the spell caster (or other). This mystic armor has an A.R. of 14 and an S.D.C. of 100 plus 10 per level of the caster; fire, lightning and cold do one-half damage.', NULL, NULL),
  ('Ritual: Call Nightlands Denizen', 3, 15, NULL, NULL, 'import', 'Nightbane RPG p.131-132', 'nightbane', '20 ft (6.1 m) per level of experience.', 'Instant', NULL, 'None', NULL, 'One hour.', 'This ritual requires a mirror or other reflective surface. At the completion of the ritual, the mirror will turn black and open into the Nightlands, calling the nearest Nightland denizen in the area (this includes Dopplegangers, Hounds, Hunters, Ashmedai and Nemtar, but not Nightbane and Nightlords). The creature may or may not answer the call, or use the breach in the Mirrorwall to cross over and cause mischief, so typically this ritual is conducted when and where the sorcerer is ready to deal with a hostile Nightlands monster. Note: This ritual will automatically awaken a Doppleganger.', NULL, NULL),
  ('Nightbane: Astral Projection', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.132', 'nightbane', 'Self', '5 minutes per level of experience.', NULL, 'None', NULL, NULL, 'The incantation sends the spell caster''s astral body into the astral plane, dimension. This magic functions exactly like the psychic sensitive ability of the same name.', 'Astral Projection', 'nightbane'),
  ('Nightbane: Charismatic Aura', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.132', 'nightbane', '60 foot radius (18.3 m)', '6 melee rounds per level of experience.', NULL, 'Standard', NULL, NULL, 'A particularly handsome tool of deception, this magic can be cast upon the spell caster or another person. The spell instantly enhances the person''s physical beauty by eight, increasing his charisma so he can charm all who behold him. Although the focal point of the spell is the person on whom it was cast, it affects everybody in a 60 foot (18.3 m) radius (emanating from the person with the charismatic aura). Thus, everybody in that radius is allowed a saving throw vs magic. Those who successfully save will not be affected at all; those who fail to save are affected and will respond accordingly. The person with a charismatic aura can invoke one of three responses: friendship/trust, power/fear, and successful deception. Friendship/Trust: The first few words spoken will set up the response. This is a statement of friendship, peace or trust which will inspire those sentiments in everyone affected. Power/Fear: A statement of power, anger, strength, or vile intent, will strike awe and fear into everyone affected. (Example: "Lay down your weapons and let us pass, lest you suffer my wrath!"). Horror Factor: 13. Successful Deception: this enables the charismatic aura person to convincingly lie like a master con-man. There is an 80% chance that those affected will believe anything he tells them. This response is triggered by a phrase like, "Trust me completely...." or "I would never lie to you."', 'Charismatic Aura', 'nightbane'),
  ('Nightbane: Cure Minor Disorders', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.132', 'nightbane', 'Touch or 10 ft (3 m).', 'Instant', NULL, 'None', NULL, NULL, 'A unique bit of curative magic that will instantly relieve minor physical disorders and illness, such as headaches, indigestion, gas, heartburn, nausea, hiccups, muscle stiffness, low fever (under 101 degrees) and similar. This invocation will also negate simple curses that inflict minor disorders.', 'Cure Minor Disorders', 'nightbane'),
  ('Nightbane: Energy Field', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.132', 'nightbane', 'Self or others up to a 60 ft (18.3 m) distance.', 'One minute per level of experience.', NULL, 'None', NULL, NULL, 'The magic creates a protective field of energy around the mystic, others, or an object. The maximum area of protection is about 8 ft (2.4 m), which means it can protect a small roomful of people (about 6 to 8 individuals). The energy field appears as a semitransparent wall or bubble that shimmers with a blue-white light. The field normally provides a total protection of 60 S.D.C., but is doubled at ley lines and tripled at ley line nexuses.', 'Energy Field', 'nightbane'),
  ('Night Vision', 4, 6, NULL, NULL, 'import', 'Nightbane RPG p.133', 'nightbane', 'Self or others by touch.', '5 minutes per level of experience.', NULL, 'None', NULL, NULL, 'This invocation gives the character the power to see in absolute darkness; range of the vision: 200 ft (61 m) plus 100 feet (30.5 m) per level of experience.', NULL, NULL),
  ('Nightbane: Shadow Meld', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.133', 'nightbane', 'Self', 'Two minutes per level of experience.', NULL, 'None.', NULL, NULL, 'This unique magic enables the mage to step into shadows, becoming totally invisible, even to a see-the-invisible spell. The shadow must be at least five feet (1.5 m) tall to become an effective hiding place. The shadow serves as a superior means of hiding or moving unseen. The mage can move, walk, or run throughout the length of shadows or from shadow to shadow. While in shadow/darkness, the mage prowls at 60% proficiency (or at +15% to normal skill, whichever is higher). Intense light will dispel the shadow, leaving the mage revealed. Of course, sanctuary can be found by fleeing into another shadow. Feeble light, less than 10 torches or 300 watts, will only create more shadows. While hidden in shadows, the character is still susceptible to magic, psychic and physical attacks, although attackers are at -5 to strike him (because they cannot see him). Area effect magic does not suffer any penalty. Infrared optics are the only means that can be used to see somebody in a shadow.', 'Shadow Meld', 'nightbane'),
  ('Nightbane: Trance', 4, 7, NULL, NULL, 'import', 'Nightbane RPG p.133', 'nightbane', 'Touch or within 12 ft (3.65 m).', '5 minutes per level of experience.', NULL, 'Standard.', NULL, NULL, 'This enchantment places another person into a zombie-like state in which the entranced person is in a hypnotic daze, unaware of his environment or the happenings around him. He cannot formulate thoughts, use skills, or act on his own. While entranced, the individual is only aware of the enchanter''s voice and will follow extremely simple commands, such as stay, sit, follow me, get inside, lay down, give me your hand, etc. The entranced victim cannot engage in any type of combat, nor any actions that require skill or thought, and offers no resistance. The magic is meant to incapacitate more than it is to enslave. Evil sorcerers often use trance on prisoners or on the intended victims of a human sacrifice. While entranced, the person cannot be made to reveal secrets, betray a friend, harm himself, or act against his alignment. All physical attributes function as if they are half of what they really are, thus, a speed of 10 is 5 while entranced. The victim of a trance will remember nothing of the events that occurred while entranced. Cannot affect people inside vehicles.', 'Trance', 'nightbane'),
  ('Charm Weapon', 5, 12, NULL, 'The book''s own index (printed 126-127) lists this at 15 P.P.E.; the stat block prints 12, which is stored.', 'import', 'Nightbane RPG p.133-134', 'nightbane', 'Touch', '12 hours per level of the spell caster.', NULL, 'Standard', NULL, '1 hour', 'This invocation temporarily enchants a weapon, to make it more effective against supernatural beings. The weapon will inflict double damage to any supernatural creature, or normal damage to beings who cannot normally be harmed by most weapons (like vampires or entities). For example, a sword that normally inflicts 1D8 damage will do 2D8 against Nightspawn or other supernatural beings, and 1D8 against vampires. This ritual will affect both hand to hand and missile weapons; if a missile weapon is thus enchanted, any missiles (bullets or arrows, for example) it fires will be automatically charmed. Saving Throw: The weapon to be charmed has a saving throw, with a bonus of +1 if it is a missile weapon, or +3 if it is a high-tech weapon (a gun, for example).', NULL, NULL),
  ('Midnight Wind', 5, 12, NULL, NULL, 'import', 'Nightbane RPG p.135', 'nightbane', '150 ft (45.7 m) area.', 'One melee round per level of experience.', NULL, 'Dodge', NULL, NULL, 'This incantation creates a cold, hurricane-force wind and also temporarily darkens the sky in the area. Lights will dim and the temperature will drop 15 degrees Fahrenheit in the area affected. Once per melee round, the spell caster can unleash a powerful gust of wind against one target (+3 to strike), inflicting 3D6 points of damage. If the damage is greater than half the P.S. of the target, the victim is also knocked down by the freezing blast of wind.', NULL, NULL),
  ('Ritual: Call Nightlord', 6, 25, NULL, NULL, 'import', 'Nightbane RPG p.137', 'nightbane', '1 mile (1.6 km) per level of experience, or 10 miles (16 km) per level of experience if a specific Nightlord is being called.', 'Instant', NULL, 'None', NULL, '1 hour', 'The sorcerer can contact the Nightlords with this ritual. When successfully completed, the contacted Ba''al or one of his avatars will sense they are being called, and will magically know where the call came from. The magic can reach across the Mirrorwall into both Earth and the Nightlands. There are two versions of this enchantment; one will call the nearest Nightlord or avatar in the area, whether he is on Earth or the Nightlands. The second version calls one specific Ba''al or one of his avatars. Calling a Nightlord when he does not wish to be disturbed is, of course, a very dangerous pastime. Note: This spell is very rare outside the Cults of Night.', NULL, NULL),
  ('Paralysis: Superior', 7, 25, NULL, NULL, 'import', 'Nightbane RPG p.139', 'nightbane', '30 ft (9.1 m).', '1 minute per level of experience.', NULL, 'Standard.', NULL, NULL, 'This magic temporarily incapacitates its victim, paralyzing him completely. In this state the victim cannot move, or even speak. If damage is inflicted on the victim, the spell is broken and he can move once again. A successful save means the magic has no effect.', NULL, NULL),
  ('Ritual: An Eye for An Eye', 7, 30, NULL, NULL, 'import', 'Nightbane RPG p.139', 'nightbane', 'Self or others by touch.', '3 minutes per level of experience.', NULL, 'None', NULL, '1 minute (4 melee rounds)', 'This powerful enchantment causes any attack that inflicts damage on the spell caster to magically wound the attacker as well! For example, if an assassin stabs the magician and inflicts 7 points of damage, an identical wound would appear on the assassin''s back for the same amount of damage. Only damage that harms the caster''s personal S.D.C. and Hit Points is affected by this spell. The caster remains injured by the attacks and must heal his/her wounds through other means.', NULL, NULL),
  ('Nightbane: Luck Curse', 8, 35, NULL, NULL, 'import', 'Nightbane RPG p.140', 'nightbane', 'Touch or within 10 ft (3.0 m).', '24 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'The incantation inflicts the person with bad luck. The victim''s normal bonuses to strike, parry, dodge, and initiative, and roll with punch, are all reduced to zero; no bonuses! Critical strikes do normal damage (except a natural 20 always does double damage) a death or knockout/stun punch does only 1D4 damage. Kick attacks have a 60% chance of causing the character to trip and fall down. Prowl skill turns into a clumsy roll, making noise every time it is tried. All skills are at a -40%, but only during critical situations. The game master can also add other minor occurrences of bad luck. Only a remove curse invocation can negate the effect of this enchantment before its duration elapses.', NULL, 'nightbane'),
  ('Nightbane: Metamorphosis: Human', 8, 35, NULL, NULL, 'import', 'Nightbane RPG p.140', 'nightbane', 'Self, or other by ritual.', '20 minutes per level of experience.', NULL, 'None.', NULL, NULL, 'A human mage can change his shape, altering his physical structure. The ultimate disguise, the character can change his height, weight, age, hair color, hair length, skin color, gender, and features. A non-human being can transform itself to appear completely human. Note: Nightbane cannot alter their Morphus with this spell, only their Facade. For some reason, their true shape is immune to shape-changing magicks. To attempt to impersonate a real, existing person, the arcanist must have the disguise skill, even though he/she is mentally molding his/her features through magic. A good photograph is required. The success ratio for imitating/impersonating the appearance of a real person is the mage''s disguise skill +20%. The better he knows the person the more complete the disguise. In a ritual version of this same magic, the mage can metamorphosize somebody else, rather than himself. Also in the ritual magic, the mage can metamorphosize someone else into an exact duplicate of himself. Furthermore, a captive at the ceremony can be duplicated without flaw. Note: The metamorphosis process only changes the appearance of the body. The transformed person retains his own voice, memory, skills, and attributes/abilities.', 'Metamorphosis: Human', 'nightbane'),
  ('Nightbane: Minor Curse', 8, 30, NULL, NULL, 'import', 'Nightbane RPG p.140', 'nightbane', 'Touch or within 10 ft (3.0 m).', '24 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'The spell caster can inflict a curse in the form of minor physical disorders that cause a constant irritation. Such disorders include: Fever: -2 on initiative, -5% on all skills, reduce speed and endurance (P.E.) by 25%. Fever ranges from 99 to 102 degrees, victim feels drained, tired, and uncomfortable. Gas: Some indigestion and nausea, bloated feeling. Farts once every two melees (pee-u). -2 on initiative, sneak attacks and prowls are impossible. Headache: Dull, throbbing headache; sleep and concentration are difficult. All skills are -10% and all saving throws are -1 (lack of focus). Hiccups: Annoying; interrupts speaking constantly. Language skills are -15%, mental affinity (M.A.) is reduced by half. Prowl is impossible. Spells can still be cast with little difficulty. Ingrown Toenail: Painful to walk, victim limps. Reduce speed by 1/3, prowl is -10%, climb is -15%. Itching and Rash: Very uncomfortable; almost maddening itch that can be relieved only by scratching. Reduce mental affinity (M.A.) by half, -4 on initiative and minus one attack per melee. Pimples: Dozens of pimples break out all over the face and arms. Reduce physical beauty by half. Nausea: Stomach ache, loose bowels and vomiting slow this poor victim down. Reduce speed to a comfortable half normal (running faster is possible, but there is a 50% chance of vomiting). Sudden movements, bumpy rides, or high speed chases (50 mph/80 kmph or faster) have a 60% chance of inducing vomiting or diarrhea. The victim is -6 to strike, parry and dodge while throwing up, and has no initiative. Runny Nose and Cough: The victim suffers from a nagging, constant cough, watering eyes and runny nose. Reduce physical beauty by 25%. Prowling and sneak attacks are impossible. Spell casting is unimpaired. Vertigo: The character gets dizzy when running (speeds higher than 8), during high speed chases (50 mph/80 kmph or faster), or when exposed to heights (must be looking out a window or standing on a ladder or ledge, and so on, higher than 10 ft/3.0 m). When the vertigo hits, the character is almost helpless; reduce attacks per melee to one, no initiative, -8 to strike, parry and dodge. The vertigo will last as long as the victim is exposed to what induces it. No normal medicine or cures will rid a character of a curse. Only a remove curse incantation can do it, or waiting until the duration time of the curse elapses. A negation spell can be tried, but it has only a 25% possibility of success.', NULL, 'nightbane'),
  ('Negation', 8, 30, NULL, NULL, 'import', 'Nightbane RPG p.141', 'nightbane', 'Touch or within 60 ft (18.3 m).', 'Instant', NULL, 'Special (ritual magic has a greater chance of success).', NULL, NULL, 'This incantation will instantly cancel the effects or influence of most magic. To determine whether the negation is successful or not roll a saving throw. If the roll is a successful save against the magic used, its influence is immediately destroyed/negated/canceled. 12, 13, 14 or 15 is needed for spell magic depending on the experience level of the magic. A failed save means the negation attempt did not work. Try again if sufficient P.P.E. is available. Negation will not work against possession, exorcism, constrain being, banishment, talisman, amulet, enchanted objects, symbols/circles of protection, wards, summoning magic, zombies, golems, restoration or healing/cures. Negation can be attempted to cancel a curse, but only has a 25% possibility of succeeding, and thats only if the saving throw was successful. It also has no effect against psychic abilities or Nightspawn talents.', NULL, NULL),
  ('Nightlands Portal', 8, 50, NULL, NULL, 'import', 'Nightbane RPG p.141', 'nightbane', '20 ft (6.1 m) area.', '1 minute per level of experience.', NULL, 'None.', NULL, 'One hour', 'The sorcerer has the ability to open a dimensional gateway into the Nightlands (or, if cast in the Nightlands, to Earth). The portal reaches the corresponding place in that shadowy dimension. So, for example, if this invocation is conducted in an Earth city, the doorway will open to the middle of its corresponding Nightlands City-state. While the gate is open, anybody can cross into or out of the Nightlands, or vice-versa.', NULL, NULL),
  ('Temporary Enchantment', 8, 70, NULL, 'The book''s own index (printed 126-127) lists this at 30 P.P.E.; the stat block prints 70, which is stored.', 'import', 'Nightbane RPG p.141', 'nightbane', 'Touch', 'One week per level of the caster.', NULL, 'Standard.', NULL, NULL, 'This incantation enchants a weapon, allowing it to inflict double damage to supernatural creatures, or normal damage to creatures normally unaffected by normal weapons. A missile weapon enchanted in this manner will extend the enchantment to any ammunition it fires. The weapons get a saving throw, at +1 if it is an archaic missile weapon (like a bow or crossbow), or at +3 if it is a high-tech weapon (like a gun).', NULL, NULL),
  ('Temporary Insanity', 9, 45, NULL, NULL, 'import', 'Nightbane RPG p.143', 'nightbane', 'Touch or 20 ft (6.1 m).', '24 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'This invocation temporarily renders the person insane! Roll on the insanity tables to determine the exact nature of the curse. The effects of the madness can only be reversed by a remove curse (a negation has a 25% chance of working). If the spell is cast against a player character, the change in behavior should be role-played fully.', NULL, NULL),
  ('Bind Nightbane', 10, 70, NULL, NULL, 'import', 'Nightbane RPG p.144', 'nightbane', '200 foot (61.0 m) radius circle.', '2 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'This incantation is designed to exert power over the Nightbane. It is known only by a few sorcerer brotherhoods and is very rarely passed on to outsiders. If the Nightbane(s) in the area fails his saving throw, he is partially controlled by the mage. The sorcerer can prevent the Nightbane from leaving the boundaries of the circle (or, alternatively, he can expel the Nightbane and make it impossible for him to enter the area affected). He can also keep the Nightbane from moving (the character can save every melee round to fight the paralysis; a successful save breaks the paralysis but does not remove the circle''s power). More importantly, the caster can force the Nightbane to remain in either Morphus or Facade form! Typically, the arcanist will choose the weaker Facade for his victim(s).', NULL, NULL),
  ('Bonding', 10, 80, NULL, NULL, 'import', 'Nightbane RPG p.144', 'nightbane', '12 miles (19.2 km) per level of experience.', 'Varies with each individual spell.', NULL, 'Standard, with a -1 penalty to save.', NULL, NULL, 'Bonding is a powerful ritual incantation that combines magic to strike at somebody from a great distance. The arcanist makes a clay, straw or rag doll in the image of a man or woman. Then a lock of hair or fingernail clippings from the intended victim is glued to the doll effigy. To complete the magic the incantation is performed and the victim''s true name (first, middle and last) must be known (if the person has no middle name, only the first and last must be known). When this has been done, the doll is magically linked to that specific individual. This means that non-energy magic, like befuddle, fear, breathe without air, trance, calling, heal wounds, compulsion, sickness, curses and so on, can be cast on the doll effigy and it will affect the real person. Summoning and protection magic, as well as energy magic like energy bolt, call lighting, fire bolt, telekinesis, etc., cannot be used on the doll with any effect. Pins and needles can be used to inflict stabbing pain into the victim. This is done by stabbing the doll with the instruments of torture. The victim will double over with pain, losing all but one attack that melee and is -4 to strike, parry and dodge. Despite the great pain, the needle inflicts only one S.D.C. point of damage each time. Fire can be used to wear a character down with fever-like symptoms: feels like he''s burning up from heat, sweats profusely, speed is reduced by 25%, skills are at -5%, -1 to strike, parry and dodge. Needles and fire can be inflicted for a total of one minute per level of experience of the enchanter. The magic spells or ritual magic will last as long as the normal duration for that particular spell. No more than two spells can be inflicted on the victim at any one time. The initial bonding ritual requires 80 P.P.E. plus the P.P.E. cost of whichever invocation is being cast on the victim. The mystic assault happens as soon as the spell is finished and will last the usual length of that spell. Shortly after the spell is cast the bonding magic becomes too weak to transmit other magic. However, the link between the living person and the doll continues to exist. The mystic can bring the bonding magic back up to full power (and be able to inflict more magic on its victim) by repeating the bonding incantation and spending 40 P.P.E. points. Each renewal provides the sorcerer with the opportunity to inflict more magic on his victim or one minute per level of experience to use needles or fire on the doll. Remember, no more than two spells/invocations can be used on a person at any given time. Consequently, if the victim is still under the effect of an invocation, only one new one can be cast upon him. The victim always gets to save vs each magic spell. A successful save means it has no effect; try again.', NULL, NULL),
  ('Curse: Paranoia', 10, 70, NULL, NULL, 'import', 'Nightbane RPG p.145', 'nightbane', 'Touch or 20 ft (6.1 m).', '24 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'This curse inflicts extreme paranoia on its victim. The poor individual will become convinced that he can trust or believe no one, regardless of past friendships. The afflicted character will see everybody as sinister and treacherous beings, probably associated with supernatural evil. They all covet his possessions, knowledge or death. Any act of aggression toward the paranoid will convince him of treachery and he will react in kind. General reactions will include secretiveness, hiding data and items of importance, staying aloof and alone, lying, and an immediate, hostile counter-response to any perceived threats.', NULL, NULL),
  ('Summon Nightlands Denizen', 10, 75, NULL, NULL, 'import', 'Nightbane RPG p.145', 'nightbane', 'Immediate', '1 hour per level of experience.', NULL, 'None.', NULL, NULL, 'This ritual summons to Earth a Nightland creature of the caster''s choice, limited to Hounds, Hunters and Dopplegangers. The Doppleganger of a living person, if one exists (Game Masters'' choice or 20% chance) can be summoned in this manner. This ritual does not provide any means to control the summoned creature, so the sorcerer must be prepared to deal with the newcomer in some other way. When the duration of the spell elapses, the creature is sent back to its homeland.', NULL, NULL),
  ('Nightbane: Wards', 10, 90, NULL, NULL, 'import', 'Nightbane RPG p.145', 'nightbane', 'Varies with type.', 'Effects vary with type.', NULL, 'Standard', NULL, NULL, 'The ward''s invocation creates mystic symbols used to protect items of value, to protect dwellings, and as booby traps. The ward can be cast on a door or window, a section of floor, a cabinet or on a specific item, such as a book or statue. The ward symbols on the object are always obvious, to serve as a warning. When somebody other than the sorcerer who created them touches the object, a spell is triggered. The following wards can be created. Each ward invocation will create two separate wards, the ritual invocation will create three. The object to be warded must be present. Alarm: A screeching, siren-like noise is instantly sounded and continues to blare for TEN minutes. The sound can be easily heard through closed doors up to 100 ft (30.5 m) away. Fear: An aura of fear engulfs everybody within a 20 foot (6.1 m) area of the ward. Each person must roll to save vs magic or be overwhelmed by terror. Effects are identical to the second level fear invocation. Fire Bolt: The person touching the item is struck by a fire bolt causing 6D6 damage; no saving throw is applicable. Same as the fourth level invocation. Paralysis (lesser): The ward temporarily paralyses the person''s hand and arm for 1D4 hours. The effects are identical to the third level invocation. Sleep: The ward will put to sleep everybody within 10 foot (3.0 m) of it. Each person must roll to save versus magic. The sleep lasts for 6D6 minutes. As per the fifth level spell. Agony: The person who touches the object is racked with agony for 2D8 melees. The effects are identical to the seventh level invocation. Curse (minor): Inflicts a minor curse identical to the eighth level invocation except that it will linger for 1D6 weeks. Curse (phobia): Inflicts a phobia curse identical to the ninth level spell except that it will linger for 1D4 weeks. Banishment (counts as two wards): will instantly force lesser supernatural beings from the area, just like the tenth level invocation. Plus, the creature must leave the object where it rests. After a ward has been triggered, its magic is used up and it disappears. A ward can last for centuries if left undisturbed. The life span of the ward is 150 years per level of the arcanist.', NULL, 'nightbane'),
  ('Control Nightlands Denizen', 11, 85, NULL, NULL, 'import', 'Nightbane RPG p.146', 'nightbane', '30 ft (9.1 m)', '24 hours per level of experience.', NULL, 'Standard.', NULL, NULL, 'An incantation specially designed to control the servants of the Nightlords (Hounds, Hunters and Dopplegangers). This ritual does not summon the creatures, but enables the sorcerer to control them when encountered, or if summoned through a different spell. The sorcerer can control two Dopplegangers or one Hound or Hunter every time the incantation is used. The creatures gets to make a saving throw vs magic. This saving throw is at +4 if the sorcerer is directly working against the Nightlords, and at -4 if the mystic is serving the Nightlords, directly or indirectly. A successful save means the creature is not controlled by the arcanist. A failed roll means it will obey the arcanist to the best of its ability. At the end of the mandatory service to the arcanist, the mage can try to renew his control by using the invocation once again. Alternatively, he may try to banish the creature or just let his control slip away. If the latter happens, the creature may decide to turn against the sorcerer.', NULL, NULL),
  ('Curse: Neurosis', 11, 95, NULL, NULL, 'import', 'Nightbane RPG p.146', 'nightbane', 'Touch', '24 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'The incantation afflicts its victim with a neurotic disorder. The sorcerer can implant one specific neurosis or roll on the random neurosis table of the insanity section. The insanity is temporary and fades away several days after the duration time has elapsed.', NULL, NULL),
  ('Nightlands Passage', 11, 100, NULL, NULL, 'import', 'Nightbane RPG p.146', 'nightbane', '10 ft (3.0 m) radius per level of experience.', 'Instant', NULL, 'Standard if unwilling to be transported.', NULL, NULL, 'This invocation instantly transports the caster and anybody/anything within the radius of the effect (10 ft/3.0 m per level of experience) into or out of the Nightlands. The caster and other "passengers" will be transported into the corresponding point in the Nightlands. Unwilling passengers get a saving throw vs magic; a success means they remain behind as the rest are teleported out.', NULL, NULL),
  ('Summon Nightlord Avatar', 11, 150, NULL, NULL, 'import', 'Nightbane RPG p.147', 'nightbane', 'Immediate', '1 hour per level of experience.', NULL, 'Standard if the Avatar resists the summons (+5 to save).', NULL, NULL, 'This risky ritual summons a specific Avatar of a Nightlord. The Avatar must be known by its given name and must be still active/living. The invocation will summon the Avatar from anywhere in the Nightlands or Earth, but if the Avatar is reluctant to be summoned, he resists the spell with an additional +5 to his saving throw. A reluctantly summoned avatar will arrive ready to fight and punish the sorcerer who dares to summon him. Even one who does not resist the summoning may have done so just to be able to teach the impudent mortal a lesson. The invocation does not offer any way to control or restrain the creature. For the most part, it is only used by cultists and servants of the Ba''al.', NULL, NULL),
  ('Nightbane: Summon and Control Rain', 12, 200, NULL, NULL, 'import', 'Nightbane RPG p.148', 'nightbane', 'Immediate area around the mage, or up to 10 miles (16 km) away per level of experience.', '1 hour per level of experience.', NULL, 'None.', NULL, NULL, 'The sorcerer can create a rainstorm out of thin air. The rain can be controlled to be a drizzle, light rain or downpour. One mile (1.6 km) per level of experience can be affected by the rain. A heavy storm will reduce visibility and slow travel.', 'Summon and Control Rain', 'nightbane'),
  ('Enchant Weapon', 13, 300, '300 for a hand-held weapon; 600 to enchant a missile weapon (gun, bow, crossbow)', NULL, 'import', 'Nightbane RPG p.148', 'nightbane', 'Touch', 'Permanent, or until the weapon is destroyed.', NULL, 'None.', NULL, NULL, 'This invocation is similar to the charm weapon spell but is more powerful. An enchanted weapon will permanently charge a weapon with mystical energy, enabling it to damage supernatural beings, including vampires. It will inflict double damage to all supernatural creatures (including Nightbane, Guardians, elementals and dragons), but does normal damage to humans and other S.D.C. beings. Missile weapons (guns, bows, crossbows, etc.) can be enchanted in the same manner, but it costs double the P.P.E. (600 points). Any projectile fired by the enchanted weapon will be considered to be enchanted and inflict double damage to supernatural foes.', NULL, NULL),
  ('Nightbane: Protection Circle: Superior', 13, 250, NULL, NULL, 'import', 'Nightbane RPG p.148', 'nightbane', 'Radius of the circle.', '24 hours, but can be reactivated immediately at a cost of 20 P.P.E.', NULL, 'None.', NULL, NULL, 'In principle and function, the superior protection circle is just like the simple circle, only stronger. The sorcerer must recite the invocation while drawing the circle in chalk or any substance. 250 P.P.E. are needed to initially create the circle, but a mere 20 P.P.E. will reactivate it. Anybody with sufficient P.P.E. and desire can reactivate a protection circle. The circle ceases to function only if it is seriously marred. The superior protection circle will protect everybody inside its radius by preventing any supernatural creatures from coming any closer than 20 ft (6.1 m) from its edge. Even greater beings (including the Nightlords) are held at bay. Lesser beings cannot stand to be within line of sight of the circle and are forced to leave (even if it''s only to the next room with the door shut). This means no attacks are possible from the lesser beings. The circle also provides the following bonuses to all occupants: +5 to save vs all magic and psychic attacks, impervious to possession, +8 to save vs horror factor. Plus it provides an extra 10 P.P.E. to each mage and 10 I.S.P. to each psychic. Of course, the characters are vulnerable to conventional weapons and thrown objects.', 'Protection Circle: Superior', 'nightbane'),
  ('Summon Storm', 13, 300, NULL, NULL, 'import', 'Nightbane RPG p.148', 'nightbane', 'Immediate area around the mage or up to 10 miles (16 km) away.', '1 hour per level of experience.', NULL, 'None.', NULL, NULL, 'The spell caster can create a destructive storm out of thin air. A rainstorm will create a torrential downpour of 4 inches of rain per hour, causing flooding even in cities. Flooded roads will immobilize all vehicles (water is 3 to 5 ft/0.9 to 1.5 m in height). Poor visibility will slow travel to about 20 mph (32 kmph). Traveling fast is likely to cause an accident. Roll on the following table for every two miles (3.2 km) traveled. 01-30 No problem, keep going. 31-39 Vehicle stalls out. 1-50% chance of restarting. 40-69 Vehicle runs off road and is immobilized. 70-00 Vehicle crashes into an obstacle or another vehicle. Vehicle is immobilized. All passengers roll 2D6 damage for every 10 mph (16 kmph) of vehicle speed. The storm is accompanied by damaging winds gusting to 35 and 45 mph (54 to 72 kmph). The rain and wind makes air travel impossible. A windstorm may be accompanied by light rain, but the real threat is high winds. Winds gust up to 70 and 90 mph (112 to 144 kmph), uprooting small trees, knocking down tree branches and electrical wires, and even overturning an occasional car. Travel on foot is very difficult, reducing a character''s speed by 90%. Travel in automobiles is slowed to about 20 mph (32 kmph). Traveling any faster is likely to cause the vehicle to run off the road and flip over. Roll 40% + 10% for every 10 mph (16 kmph) above 20 mph (32 kmph). Roll once for every 4 miles (6.4 kmph) of travel. Air travel is extremely hazardous.', NULL, NULL),
  ('Summon Nightlord', 13, 425, NULL, NULL, 'import', 'Nightbane RPG p.148-149', 'nightbane', 'Immediate', '30 minutes per level of experience.', NULL, 'If the Nightlord is unwilling, he saves at +8.', NULL, NULL, 'This dangerous and little-known invocation will summon a Nightlord from anywhere on Earth or the Nightlands. However, if the Nightlord does not wish to be summoned, his normal saving throw vs magic is at +8. If he fails his save, the Nightlord will arrive in a state of rage, ready to destroy the sorcerer unless he can be somehow restrained or convinced otherwise. For the most part, the ritual is cast only by sorcerers who are allied or work for the Nightlord, and when their master is expecting the summons. The title/given name (not the real name) of the Nightlord is necessary to cast the invocation.', NULL, NULL);

-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'nightbane spells inserted' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%';

SELECT 'every one cites this book by page' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND source = 'import';

SELECT 'every one carries a cost' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND ppe > 0;

SELECT 'every one carries a description' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND length(description) > 40;

SELECT 'the retellings are prefixed and tagged' AS assertion, count(*) AS got, 12 AS want
  FROM spells WHERE system = 'nightbane' AND name LIKE 'Nightbane: %' AND tradition = 'nightbane';

SELECT 'the new invocations carry no tradition' AS assertion, count(*) AS got, 27 AS want
  FROM spells WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND tradition IS NULL AND name NOT LIKE 'Nightbane: %';

SELECT 'the detector-approved retellings are linked' AS assertion, count(*) AS got, 9 AS want
  FROM spells WHERE system = 'nightbane' AND same_spell_as IS NOT NULL;

SELECT 'the book disagreeing with itself is recorded' AS assertion, count(*) AS got, 3 AS want
  FROM spells WHERE system = 'nightbane' AND variant_note IS NOT NULL;

SELECT 'the variable cost carries its note' AS assertion, count(*) AS got, 1 AS want
  FROM spells WHERE system = 'nightbane' AND ppe_note IS NOT NULL;

SELECT 'and every link resolves to a real row' AS assertion, count(*) AS got, 0 AS want
  FROM spells r WHERE r.system = 'nightbane' AND r.same_spell_as IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM spells t WHERE t.name = r.same_spell_as);

